// ❌ Primitive obsession : rien n'empêche un email invalide de circuler
void register(String email) { /* validé où ? partout ? nulle part ? */ }

// ✅ Replace Primitive with Object : la règle vit dans le type
record Email(String value) {
    Email {
        if (value == null || !value.contains("@"))
            throw new IllegalArgumentException("email invalide");
    }
}
void register(Email email) { /* impossible d'arriver ici avec un email invalide */ }

// ❌ Cognitive élevée : gardes imbriquées (chaque niveau ajoute un malus)
boolean eligible(User u) {
    if (u != null) {
        if (u.isActive()) {
            if (u.getAge() >= 18) {
                if (!u.isBanned()) {
                    return true;
                }
            }
        }
    }
    return false;
}

// ✅ Même logique, cognitive faible : early return, tout à plat
boolean eligible(User u) {
    if (u == null)        return false;
    if (!u.isActive())    return false;
    if (u.getAge() < 18)  return false;
    if (u.isBanned())     return false;
    return true;
}
